var T0=1.2, P=112/60, X0=-266, SPD=830/(112/60), TL=-136, TW=272.6;
var xc=TL+TW*(textIndex-0.5)/textTotal;        // this letter's centre
var ti=(xc-X0)/SPD;                              // when the band centre crosses it, after each cycle start
function s(t){ if(t<=0) return 0; var w=22, z=0.55, wd=w*Math.sqrt(1-z*z);
  return 1-Math.exp(-z*w*t)*(Math.cos(wd*t)+z*w/wd*Math.sin(wd*t)); }
var v=0;
if(time>=T0){ var u=time-T0-ti, k=Math.floor((u+0.35)/P), tau=u-k*P; v=s(tau+0.12)-s(tau-0.10); }
v/1.2*100;

